INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eoDeuBwEw7c', 1, '{"title":"甘草泻心汤","description":"<p>62、$f{甘草泻心汤} 6味 </p>\n<p>$u{甘草}$w{四两。炙}    $u{干姜}$w{三两}    $u{黄芩}$w{三两}    $u{半夏}$w{半升(洗)}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上六味。以水一斗。煮取六升。去滓。再煎取三升。温服一升。日三服。$a{按：上生姜泻心汤法。本云理中人参黄芩汤。今详泻心以疗痞。痞气因发阴而生。是半夏、生姜、甘草泻心汤三方皆本于理中也。其方必各有人参。今甘草泻心汤中无者。脱落之也。又按《千金》并《外台秘要》。治伤寒食用此方。皆有人参。知脱落无疑。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":62,"yaoCount":6,"drinkNum":3,"yaoList":["甘草","干姜","黄芩","半夏","黄连","大枣"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"四两","weight":400,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"一两","weight":100,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '62、$f{甘草泻心汤} 6味 $u{甘草}$w{四两。炙} $u{干姜}$w{三两} $u{黄芩}$w{三两} $u{半夏}$w{半升(洗)} $u{黄连}$w{一两} $u{大枣}$w{十二枚。擘} 上六味。以水一斗。煮取六升。去滓。再煎取三升。温服一升。日三服。$a{按：上生姜泻心汤法。本云理中人参黄芩汤。今详泻心以疗痞。痞气因发阴而生。是半夏、生姜、甘草泻心汤三方皆本于理中也。其方必各有人参。今甘草泻心汤中无者。脱落之也。又按《千金》并《外台秘要》。治伤寒食用此方。皆有人参。知脱落无疑。}', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
