INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('diKmdsS7YL3', 1, '{"title":"瓜蒂散","description":"<p>66、$f{瓜蒂散} 2味 </p>\n<p>$u{瓜蒂}$w{一分(熬黄)}    $u{赤小豆}$w{一分}($u{香豉}$w{热汤合之})。</p>\n<p>\t上二味。各别捣筛。为散已。合治之。取一钱匕。以香豉一合。用热汤七合。煮作稀糜。去滓。取汁和散。温顿服之。不吐者。少少加。得快吐乃止。$a{诸亡血虚家。不可与瓜蒂散。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":66,"yaoCount":3,"drinkNum":1,"yaoList":["瓜蒂","赤小豆","香豉"],"fangList":[],"fangYaoList":[{"yaoId":"zdySy9e78kG","amount":"一分(半钱匕)","weight":5,"suffix":"","showName":"瓜蒂","extraProcess":"切"},{"yaoId":"xoqRCmUZylQ","amount":"一分(用半钱匕)","weight":5,"suffix":"","showName":"赤小豆","extraProcess":"切"},{"yaoId":"sx4xviDfH00","amount":"一合","weight":100,"suffix":"","showName":"香豉","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '66、$f{瓜蒂散} 2味 $u{瓜蒂}$w{一分(熬黄)} $u{赤小豆}$w{一分}($u{香豉}$w{热汤合之})。 上二味。各别捣筛。为散已。合治之。取一钱匕。以香豉一合。用热汤七合。煮作稀糜。去滓。取汁和散。温顿服之。不吐者。少少加。得快吐乃止。$a{诸亡血虚家。不可与瓜蒂散。}', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
