INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VRlRjs96y9f', 1, '{"title":"黄连汤","description":"<p>69、$f{黄连汤} 7味 </p>\n<p>$u{黄连}$w{三两}    $u{甘草}$w{三两。炙}    $u{干姜}$w{三两}    $u{桂枝}$w{三两。去皮}    $u{人参}$w{二两}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上七味。以水一斗。煮取六升。去滓。温服。昼三夜二。$a{疑非仲景方。（康平本作“疑非仲景法“）}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":69,"yaoCount":7,"drinkNum":5,"yaoList":["黄连","甘草","干姜","桂枝","人参","半夏","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"5GP5Zyu6577","amount":"三两","weight":300,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":200,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '69、$f{黄连汤} 7味 $u{黄连}$w{三两} $u{甘草}$w{三两。炙} $u{干姜}$w{三两} $u{桂枝}$w{三两。去皮} $u{人参}$w{二两} $u{半夏}$w{半升(洗)} $u{大枣}$w{十二枚。擘} 上七味。以水一斗。煮取六升。去滓。温服。昼三夜二。$a{疑非仲景方。（康平本作“疑非仲景法“）}', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
