INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('frBATbcVWJo', 1, '{"title":"去桂加白术汤","description":"<p>71、$f{去桂加白术汤} 5味 </p>\n<p>$u{附子}$w{三枚(炮。去皮。破)}    $u{白术}$w{四两}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{甘草}$w{二两。炙}</p>\n<p>\t上五味。以水六升。煮取二升。去滓。分温三服。初一服。其人身如痹。半日许复服之。三服都尽。其人如冒状。勿怪。此以附子、术。并走皮内。逐水气未得除。故使之耳。法当加桂四两。$a{此本一方二法：以大便硬。小便自利。去桂也。以大不便硬。小便不利。当加桂。附子三枚恐多也。虚弱及产妇宜减之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":71,"yaoCount":5,"drinkNum":3,"yaoList":["附子","白术","生姜","大枣","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"3枚炮","weight":300,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"四两","weight":400,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '71、$f{去桂加白术汤} 5味 $u{附子}$w{三枚(炮。去皮。破)} $u{白术}$w{四两} $u{生姜}$w{三两。切} $u{大枣}$w{十二枚。擘} $u{甘草}$w{二两。炙} 上五味。以水六升。煮取二升。去滓。分温三服。初一服。其人身如痹。半日许复服之。三服都尽。其人如冒状。勿怪。此以附子、术。并走皮内。逐水气未得除。故使之耳。法当加桂四两。$a{此本一方二法：以大便硬。小便自利。去桂也。以大不便硬。小便不利。当加桂。附子三枚恐多也。虚弱及产妇宜减之。}', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w862uueFeEF', 1, '{"title":"甘草附子汤","description":"<p>72、$f{甘草附子汤} 4味 </p>\n<p>$u{甘草}$w{二两。炙}    $u{附子}$w{二枚(炮。去皮。破)}    $u{白术}$w{二两}    $u{桂枝}$w{四两。去皮}</p>\n<p>\t上四味。以水六升。煮取三升。去滓。温服一升。日三服。$a{初服得微汗则解。能食。汗止复烦者。将服五合。恐一升多者。宜服六七合为始。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":72,"yaoCount":4,"drinkNum":3,"yaoList":["甘草","附子","白术","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"2枚炮","weight":200,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"四两","weight":400,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '72、$f{甘草附子汤} 4味 $u{甘草}$w{二两。炙} $u{附子}$w{二枚(炮。去皮。破)} $u{白术}$w{二两} $u{桂枝}$w{四两。去皮} 上四味。以水六升。煮取三升。去滓。温服一升。日三服。$a{初服得微汗则解。能食。汗止复烦者。将服五合。恐一升多者。宜服六七合为始。}', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k57jCAFS44d', 1, '{"title":"白虎汤","description":"<p>73、$f{白虎汤} 4味 </p>\n<p>$u{知母}$w{六两}    $u{石膏}$w{一斤(碎)}    $u{甘草}$w{二两。炙}    $u{粳米}$w{六合}</p>\n<p>\t上四味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":73,"yaoCount":4,"drinkNum":3,"yaoList":["知母","石膏","甘草","粳米"],"fangList":[],"fangYaoList":[{"yaoId":"PeV28d5T6et","amount":"六两","weight":600,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"一斤","weight":1600,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"六合","weight":600,"suffix":"","showName":"粳米","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '73、$f{白虎汤} 4味 $u{知母}$w{六两} $u{石膏}$w{一斤(碎)} $u{甘草}$w{二两。炙} $u{粳米}$w{六合} 上四味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SaxLOQ31yEB', 1, '{"title":"大承气汤","description":"<p>74、$f{大承气汤} 4味 </p>\n<p>$u{大黄}$w{四两($u{酒}洗)}    $u{厚朴}$w{半斤(炙。去皮)}    $u{枳实}$w{五枚。炙}    $u{芒硝}$w{三合}</p>\n<p>\t上四味。以水一斗。先煮二物。取五升。去滓。内大黄。更煮取二升。去滓。内芒硝。更上微火一两沸。分温再服。$a{得下。余勿服。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":74,"yaoCount":4,"drinkNum":2,"yaoList":["大黄","酒","厚朴","枳实","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"半斤","weight":800,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"5枚","weight":50,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"三合","weight":300,"suffix":"","showName":"芒硝","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '74、$f{大承气汤} 4味 $u{大黄}$w{四两($u{酒}洗)} $u{厚朴}$w{半斤(炙。去皮)} $u{枳实}$w{五枚。炙} $u{芒硝}$w{三合} 上四味。以水一斗。先煮二物。取五升。去滓。内大黄。更煮取二升。去滓。内芒硝。更上微火一两沸。分温再服。$a{得下。余勿服。}', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2xayBEZqQ6a', 1, '{"title":"小承气汤","description":"<p>75、$f{小承气汤} 3味 </p>\n<p>$u{大黄}$w{四两($u{酒}洗)}    $u{厚朴}$w{二两(炙。去皮)}    $u{枳实}$w{三枚(大者。炙)}</p>\n<p>\t上三味。以水四升。煮取一升二合。去滓。分温二服。$a{初服汤当更衣。不尔者。尽饮之。若更衣者。勿服之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":75,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","酒","厚朴","枳实"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"二两","weight":200,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"3枚大者","weight":40,"suffix":"","showName":"枳实","extraProcess":"切"}]}}', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '2024-09-17T00:59:48.000Z', '75、$f{小承气汤} 3味 $u{大黄}$w{四两($u{酒}洗)} $u{厚朴}$w{二两(炙。去皮)} $u{枳实}$w{三枚(大者。炙)} 上三味。以水四升。煮取一升二合。去滓。分温二服。$a{初服汤当更衣。不尔者。尽饮之。若更衣者。勿服之。}', '2024-09-17T00:59:48.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gm4F3oZHqxK', 1, '{"title":"猪苓汤","description":"<p>76、$f{猪苓汤} 5味 </p>\n<p>$u{猪苓}$w{去皮}    $u{茯苓}    $u{泽泻}    $u{阿胶}    $u{滑石}$w{(碎)各一两}</p>\n<p>\t上五味。以水四升。先煮四味。取二升。去滓。内阿胶烊消。温服七合。日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":76,"yaoCount":5,"drinkNum":3,"yaoList":["猪苓","茯苓","泽泻","阿胶","滑石"],"fangList":[],"fangYaoList":[{"yaoId":"VBp4qtisnQR","amount":"一两","weight":100,"suffix":"","showName":"猪苓","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"一两","weight":100,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"TvTXZli2dE7","amount":"一两","weight":100,"suffix":"","showName":"泽泻","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"一两","weight":100,"suffix":"","showName":"阿胶","extraProcess":"切"},{"yaoId":"u6WaDjpcWhR","amount":"一两","weight":100,"suffix":"","showName":"滑石","extraProcess":"切"}]}}', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '76、$f{猪苓汤} 5味 $u{猪苓}$w{去皮} $u{茯苓} $u{泽泻} $u{阿胶} $u{滑石}$w{(碎)各一两} 上五味。以水四升。先煮四味。取二升。去滓。内阿胶烊消。温服七合。日三服。', '2024-09-17T00:59:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Aa2jh0r1dz', 1, '{"title":"蜜煎导","description":"<p>77、$f{蜜煎导} 1味 </p>\n<p>$u{食蜜}$w{七合}</p>\n<p>\t上一味。于铜器内。微火煎。当须凝如饴状。搅之勿令焦着。欲可丸。并手捻作挺。令头锐。大如指。长二寸许。当热时急作。冷则硬。以内谷道中．以手急抱。欲大便时乃去之。又$u{大猪胆}$w{一枚。泻汁}。和少许$u{法醋}。以灌谷道内。如一食顷。当大便出宿食恶物。甚效。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":77,"yaoCount":3,"drinkNum":1,"yaoList":["食蜜","大猪胆","法醋"],"fangList":[],"fangYaoList":[{"yaoId":"IHSagd4ikNY","amount":"七合","weight":700,"suffix":"","showName":"食蜜","extraProcess":"切"}]}}', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '77、$f{蜜煎导} 1味 $u{食蜜}$w{七合} 上一味。于铜器内。微火煎。当须凝如饴状。搅之勿令焦着。欲可丸。并手捻作挺。令头锐。大如指。长二寸许。当热时急作。冷则硬。以内谷道中．以手急抱。欲大便时乃去之。又$u{大猪胆}$w{一枚。泻汁}。和少许$u{法醋}。以灌谷道内。如一食顷。当大便出宿食恶物。甚效。', '2024-09-17T00:59:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XanB29259tP', 1, '{"title":"茵陈蒿汤","description":"<p>78、$f{茵陈蒿汤} 3味 </p>\n<p>$u{茵陈蒿}$w{六两}    $u{栀子}$w{十四枚。擘}    $u{大黄}$w{二两。去皮}</p>\n<p>\t上三味。以水一斗二升。先煮茵陈。减六升。内二味。煮取三升。去滓。分三服。小便当利。$a{尿如皂荚汁状。色正赤。一宿腹减。黄从小便去也。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":78,"yaoCount":3,"drinkNum":3,"yaoList":["茵陈蒿","栀子","大黄"],"fangList":[],"fangYaoList":[{"yaoId":"UCM21bJfrih","amount":"六两","weight":600,"suffix":"","showName":"茵陈蒿","extraProcess":"切"},{"yaoId":"7fWzC6yB6Yy","amount":"14枚","weight":140,"suffix":"","showName":"栀子","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"二两","weight":200,"suffix":"","showName":"大黄","extraProcess":"切"}]}}', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '78、$f{茵陈蒿汤} 3味 $u{茵陈蒿}$w{六两} $u{栀子}$w{十四枚。擘} $u{大黄}$w{二两。去皮} 上三味。以水一斗二升。先煮茵陈。减六升。内二味。煮取三升。去滓。分三服。小便当利。$a{尿如皂荚汁状。色正赤。一宿腹减。黄从小便去也。}', '2024-09-17T00:59:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
