INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AveCrnrVaon', 1, '{"title":"桃花汤","description":"<p>87、$f{桃花汤} 3味 </p>\n<p>$u{赤石脂}$w{一斤(一半全用。一半筛末)}    $u{干姜}$w{一两}    $u{粳米}$w{一升}</p>\n<p>\t上三味。以水七升。煮米令熟。去滓。温服七合。内赤石脂末方寸匕。日三服。若一服愈。余勿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":87,"yaoCount":3,"drinkNum":3,"yaoList":["赤石脂","干姜","粳米"],"fangList":[],"fangYaoList":[{"yaoId":"1rOkrjGOCab","amount":"一斤","weight":1600,"suffix":"","showName":"赤石脂","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":100,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"一升","weight":1000,"suffix":"","showName":"粳米","extraProcess":"切"}]}}', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '87、$f{桃花汤} 3味 $u{赤石脂}$w{一斤(一半全用。一半筛末)} $u{干姜}$w{一两} $u{粳米}$w{一升} 上三味。以水七升。煮米令熟。去滓。温服七合。内赤石脂末方寸匕。日三服。若一服愈。余勿服。', '2024-09-17T00:59:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RWHrC4KZ0Jf', 1, '{"title":"猪肤汤","description":"<p>88、$f{猪肤汤} 1味 </p>\n<p>$u{猪肤}$w{一斤}    $u{白蜜}、$u{白粉}$w{(即大米粉)}</p>\n<p>\t上一味。以水一斗。煮取五升。去滓。加$u{白蜜}$w{一升}    $u{白粉}$w{五合}。熬香。和令相得。温分六服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":88,"yaoCount":3,"drinkNum":6,"yaoList":["猪肤","白蜜","白粉"],"fangList":[],"fangYaoList":[{"yaoId":"0uQxJy23uFD","amount":"一斤","weight":1600,"suffix":"","showName":"猪肤","extraProcess":"切"},{"yaoId":"IHSagd4ikNY","amount":"一升","weight":1000,"suffix":"","showName":"白蜜","extraProcess":"切"},{"yaoId":"Ghsn25eutF9","amount":"五合","weight":500,"suffix":"","showName":"白粉","extraProcess":"切"}]}}', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '2024-09-17T00:59:49.000Z', '88、$f{猪肤汤} 1味 $u{猪肤}$w{一斤} $u{白蜜}、$u{白粉}$w{(即大米粉)} 上一味。以水一斗。煮取五升。去滓。加$u{白蜜}$w{一升} $u{白粉}$w{五合}。熬香。和令相得。温分六服。', '2024-09-17T00:59:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9Llz4fGNT0z', 1, '{"title":"甘草汤","description":"<p>89、$f{甘草汤} 1味 </p>\n<p>$u{甘草}$w{二两}</p>\n<p>\t上一味。以水三升。煮取一升半。去滓。温服七合。日二服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":89,"yaoCount":1,"drinkNum":2,"yaoList":["甘草"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '89、$f{甘草汤} 1味 $u{甘草}$w{二两} 上一味。以水三升。煮取一升半。去滓。温服七合。日二服。', '2024-09-17T00:59:50.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
