INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pAJ4mZ9GpVJ', 1, '{"title":"苦酒汤","description":"<p>91、$f{苦酒汤} 3味 </p>\n<p>$u{半夏}$w{十四枚(洗。破如枣核)}    $u{鸡子}$w{一枚(去黄)。内上}$u{苦酒}$w{着鸡子壳中}</p>\n<p>\t上二味。内半夏著苦酒中。以鸡子壳置刀环中。安火上。令三沸。去滓。少少含咽之。不差。更作三剂。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":91,"yaoCount":3,"drinkNum":1,"yaoList":["半夏","鸡子","苦酒"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"14枚","weight":120,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"A05Whol2xOv","amount":"1枚","weight":100,"suffix":"","showName":"鸡子","extraProcess":"切"},{"yaoId":"uUYyOFNioq6","amount":"装鸡子壳","weight":120,"suffix":"","showName":"苦酒","extraProcess":"切"}]}}', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '91、$f{苦酒汤} 3味 $u{半夏}$w{十四枚(洗。破如枣核)} $u{鸡子}$w{一枚(去黄)。内上}$u{苦酒}$w{着鸡子壳中} 上二味。内半夏著苦酒中。以鸡子壳置刀环中。安火上。令三沸。去滓。少少含咽之。不差。更作三剂。', '2024-09-17T00:59:50.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zk4Y4z0781u', 1, '{"title":"半夏散及汤","description":"<p>92、$f{半夏散及汤} 3味 </p>\n<p>$u{半夏}$w{(洗)}    $u{桂枝}$w{去皮}    $u{甘草}$w{炙}</p>\n<p>\t上三味。等分。个别捣筛已。合治之。白饮和。服方寸匕。日三服。若不能服散者。以水一升。煎七沸。内散两方寸匕。更煮三沸。下火令小冷。少少咽之。$a{半夏有毒。不当散服。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":92,"yaoCount":3,"drinkNum":1,"yaoList":["半夏","桂枝","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"1/3方寸匕","weight":3,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"1/3方寸匕","weight":3,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"1/3方寸匕","weight":3,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '92、$f{半夏散及汤} 3味 $u{半夏}$w{(洗)} $u{桂枝}$w{去皮} $u{甘草}$w{炙} 上三味。等分。个别捣筛已。合治之。白饮和。服方寸匕。日三服。若不能服散者。以水一升。煎七沸。内散两方寸匕。更煮三沸。下火令小冷。少少咽之。$a{半夏有毒。不当散服。}', '2024-09-17T00:59:50.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
