INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pyRQHIWDFTP', 1, '{"title":"通脉四逆汤","description":"<p>95、$f{通脉四逆汤} 3味 </p>\n<p>$u{甘草}$w{二两。炙}    $u{附子}$w{大者一枚(生用。去皮。破八片)}    $u{干姜}$w{三两。强人可四两}</p>\n<p>\t上三味。以水三升。煮取一升二合。去滓。分温再服。其脉即出者愈。面色赤者。加$u{葱}$w{九茎}。腹中痛者。去$u{葱}。加$u{芍药}$w{二两}。呕者。加$u{生姜}$w{二两}。咽痛者。去$u{芍药}。加$u{桔梗}$w{一两}。利止脉不出者。去$u{桔梗}。加$u{人参}$w{二两}。$a{病皆与方相应者。乃服之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":95,"yaoCount":8,"drinkNum":2,"yaoList":["甘草","附子","干姜","葱","芍药","生姜","桔梗","人参"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚大者生","weight":150,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"}]}}', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '95、$f{通脉四逆汤} 3味 $u{甘草}$w{二两。炙} $u{附子}$w{大者一枚(生用。去皮。破八片)} $u{干姜}$w{三两。强人可四两} 上三味。以水三升。煮取一升二合。去滓。分温再服。其脉即出者愈。面色赤者。加$u{葱}$w{九茎}。腹中痛者。去$u{葱}。加$u{芍药}$w{二两}。呕者。加$u{生姜}$w{二两}。咽痛者。去$u{芍药}。加$u{桔梗}$w{一两}。利止脉不出者。去$u{桔梗}。加$u{人参}$w{二两}。$a{病皆与方相应者。乃服之。}', '2024-09-17T00:59:50.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pXal20gTiEa', 1, '{"title":"乌梅丸","description":"<p>96、$f{乌梅丸} 10味 </p>\n<p>$u{乌梅}$w{三百枚}    $u{细辛}$w{六两}    $u{干姜}$w{十两}    $u{黄连}$w{十六两}    $u{附子}$w{六两(炮。去皮)}    $u{当归}$w{四两}    $u{蜀椒}$w{四两(出汗)}    $u{桂枝}$w{六两。去皮}    $u{人参}$w{六两}    $u{黄柏}$w{六两}</p>\n<p>\t上十味。异捣筛。合治之。以$u{苦酒}（即酸醋）渍乌梅一宿。去核。蒸之五斗米下。饭熟。捣成泥。和药令相得。内臼中。与$u{蜜}杵二千下。丸如梧桐子大。先食。饮服十丸。日三服。稍加至二十丸。禁生冷。滑物。臭食等。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":96,"yaoCount":12,"drinkNum":30,"yaoList":["乌梅","细辛","干姜","黄连","附子","当归","蜀椒","桂枝","人参","黄柏","苦酒","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"ld2CqoYXh1L","amount":"300枚","weight":3000,"suffix":"","showName":"乌梅","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"六两","weight":600,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"十两","weight":1000,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"十六两","weight":1600,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"六两炮","weight":600,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"四两","weight":400,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"03dIYYkyQRn","amount":"四两","weight":400,"suffix":"","showName":"蜀椒","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"六两","weight":600,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"六两","weight":600,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"Z5xEswEFq4S","amount":"六两","weight":600,"suffix":"","showName":"黄柏","extraProcess":"切"}]}}', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '2024-09-17T00:59:50.000Z', '96、$f{乌梅丸} 10味 $u{乌梅}$w{三百枚} $u{细辛}$w{六两} $u{干姜}$w{十两} $u{黄连}$w{十六两} $u{附子}$w{六两(炮。去皮)} $u{当归}$w{四两} $u{蜀椒}$w{四两(出汗)} $u{桂枝}$w{六两。去皮} $u{人参}$w{六两} $u{黄柏}$w{六两} 上十味。异捣筛。合治之。以$u{苦酒}（即酸醋）渍乌梅一宿。去核。蒸之五斗米下。饭熟。捣成泥。和药令相得。内臼中。与$u{蜜}杵二千下。丸如梧桐子大。先食。饮服十丸。日三服。稍加至二十丸。禁生冷。滑物。臭食等。', '2024-09-17T00:59:50.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
