INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K36Ejk9BOXY', 1, '{"title":"麻黄升麻汤","description":"<p>99、$f{麻黄升麻汤} 14味 </p>\n<p>$u{麻黄}$w{二两半。去节}    $u{升麻}$w{一两一分}    $u{当归}$w{一两一分}    $u{知母}$w{十八铢}    $u{黄芩}$w{十八铢}    $u{葳蕤}$w{十八铢(一作菖蒲)}    $u{芍药}$w{六铢}    $u{天门冬}$w{六铢(去心)}    $u{桂枝}$w{六铢。去皮}    $u{茯苓}$w{六铢}    $u{甘草}$w{六铢。炙}    $u{石膏}$w{六铢(碎。绵裹)}    $u{白术}$w{六铢}    $u{干姜}$w{六铢}</p>\n<p>\t上十四味。以水一斗。先煮麻黄一两沸。去上沫。内诸药。煮取三升。去滓。分温三服。相去如炊三斗米顷。令尽。汗出愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":99,"yaoCount":14,"drinkNum":3,"yaoList":["麻黄","升麻","当归","知母","黄芩","葳蕤","芍药","天门冬","桂枝","茯苓","甘草","石膏","白术","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"二两半","weight":250,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"dgPXrO7Zcb7","amount":"一两一分","weight":125,"suffix":"","showName":"升麻","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"一两一分","weight":125,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"PeV28d5T6et","amount":"十八铢","weight":75,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"十八铢","weight":75,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"eblADTgt2Vi","amount":"十八铢","weight":75,"suffix":"","showName":"葳蕤","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六铢","weight":25,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"ovIpIDoCZlr","amount":"六铢","weight":25,"suffix":"","showName":"天门冬","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"六铢","weight":25,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"六铢","weight":25,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":null,"amount":"六铢","weight":25,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"六铢","weight":25,"suffix":"","showName":"石膏","extraProc