INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1btZEhIyYOQ', 1, '{"title":"四逆加人参汤","description":"<p>101、$f{四逆加人参汤} 4味 </p>\n<p>$u{甘草}$w{二两。炙}    $u{附子}$w{一枚(生。去皮。破八片)}    $u{干姜}$w{一两半}    $u{人参}$w{一两}</p>\n<p>\t上四味。以水三升。煮取一升二合。去滓。分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":101,"yaoCount":4,"drinkNum":2,"yaoList":["甘草","附子","干姜","人参"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚生","weight":100,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":100,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":100,"suffix":"","showName":"人参","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '101、$f{四逆加人参汤} 4味 $u{甘草}$w{二两。炙} $u{附子}$w{一枚(生。去皮。破八片)} $u{干姜}$w{一两半} $u{人参}$w{一两} 上四味。以水三升。煮取一升二合。去滓。分温再服。', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pFcpDDVzme1', 1, '{"title":"理中丸","description":"<p>102、$f{理中丸} 4味 </p>\n<p>$u{人参}    $u{干姜}    $u{甘草}$w{炙}    $u{白术}$w{各三两}</p>\n<p>\t上四味。捣筛。$u{蜜}合为丸。如鸡子黄大。以沸汤数合。和一丸。研碎。温服之。$a{日三四、夜二服。}腹中未热。益至三四丸。然不及汤。汤法：以四物依两数切。用水八升。煮取三升。去滓。温服一升。日三服。若脐上筑者。肾气动也。去$u{术}加$u{桂}$w{四两}。吐多者。去$u{术}加$u{生姜}$w{三两}。下多者还用$u{术}。悸者。加$u{茯苓}$w{二两}。渴欲得水者。加$u{术}。$w{足前成四两半}。腹中痛者。加$u{人参}。$w{足前成四两半}。寒者。加$u{干姜}。$w{足前成四两半}。腹满者。去$u{术}。加$u{附子}$w{一枚}。服汤后。如食顷。饮热粥一升许。微自温。勿发揭衣被。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":102,"yaoCount":4,"drinkNum":3,"yaoList":["人参","干姜","甘草","白术","蜜","术","桂","生姜","茯苓","附子"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":"三两($x{腹中痛者加}至四两半)","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两($x{寒者加}至四两半)","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"三两($x{渴欲饮水加}至四两半)","weight":300,"suffix":"","showName":"白术","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '102、$f{理中丸} 4味 $u{人参} $u{干姜} $u{甘草}$w{炙} $u{白术}$w{各三两} 上四味。捣筛。$u{蜜}合为丸。如鸡子黄大。以沸汤数合。和一丸。研碎。温服之。$a{日三四、夜二服。}腹中未热。益至三四丸。然不及汤。汤法：以四物依两数切。用水八升。煮取三升。去滓。温服一升。日三服。若脐上筑者。肾气动也。去$u{术}加$u{桂}$w{四两}。吐多者。去$u{术}加$u{生姜}$w{三两}。下多者还用$u{术}。悸者。加$u{茯苓}$w{二两}。渴欲得水者。加$u{术}。$w{足前成四两半}。腹中痛者。加$u{人参}。$w{足前成四两半}。寒者。加$u{干姜}。$w{足前成四两半}。腹满者。去$u{术}。加$u{附子}$w{一枚}。服汤后。如食顷。饮热粥一升许。微自温。勿发揭衣被。', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IXv2RKqQaKP', 1, '{"title":"烧裈散","description":"<p>103、$f{烧裈散} 1味 </p>\n<p>$u{妇人中裈近隐处取烧作灰}</p>\n<p>\t上一味。水服方寸匕。日三服。小便即利。阴头微肿。$a{此为愈矣。妇人病取男子裈烧服。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":103,"yaoCount":1,"drinkNum":3,"yaoList":["妇人中裈近隐处取烧作灰"],"fangList":[],"fangYaoList":[{"yaoId":"vTWUfkC7bQJ","amount":"方寸匕","weight":5,"suffix":"","showName":"妇人中裈近隐处取烧作灰","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '103、$f{烧裈散} 1味 $u{妇人中裈近隐处取烧作灰} 上一味。水服方寸匕。日三服。小便即利。阴头微肿。$a{此为愈矣。妇人病取男子裈烧服。}', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4Y9xpcc8TH4', 1, '{"title":"牡蛎泽泻散","description":"<p>104、$f{牡蛎泽泻散} 7味 </p>\n<p>$u{牡蛎}$w{(熬)}    $u{泽泻}    $u{蜀漆}$w{(煖水洗。去腥)}    $u{葶苈子}$w{(熬)}    $u{商陆根}$w{(熬)}    $u{海藻}$w{(洗。去咸)}    $u{栝楼根}$w{各等分}</p>\n<p>\t上七味。异捣。下筛为散。更于臼中治之。白饮和服方寸匕。日三服。小便利。止后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":104,"yaoCount":7,"drinkNum":1,"yaoList":["牡蛎","泽泻","蜀漆","葶苈子","商陆根","海藻","栝楼根"],"fangList":[],"fangYaoList":[{"yaoId":"MDfiJ4S7u0U","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"TvTXZli2dE7","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"泽泻","extraProcess":"切"},{"yaoId":"gFgG38KNuFm","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"蜀漆","extraProcess":"切"},{"yaoId":"jD7lvOl6QAj","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"葶苈子","extraProcess":"切"},{"yaoId":"4W7eVdfu25M","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"商陆根","extraProcess":"切"},{"yaoId":"nb7XmSpD8Iu","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"海藻","extraProcess":"切"},{"yaoId":"pyZLleBsXOb","amount":"1/7方寸匕","weight":1,"suffix":"","showName":"栝楼根","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '104、$f{牡蛎泽泻散} 7味 $u{牡蛎}$w{(熬)} $u{泽泻} $u{蜀漆}$w{(煖水洗。去腥)} $u{葶苈子}$w{(熬)} $u{商陆根}$w{(熬)} $u{海藻}$w{(洗。去咸)} $u{栝楼根}$w{各等分} 上七味。异捣。下筛为散。更于臼中治之。白饮和服方寸匕。日三服。小便利。止后服。', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YTuXIggeqTY', 1, '{"title":"四逆散","description":"<p>105、$f{四逆散} 4味 </p>\n<p>$u{甘草}$w{炙}    $u{枳实}$w{(破。水渍。炙干)}    $u{芍药}    $u{柴胡}</p>\n<p>\t上四味。各十分。捣筛。白饮和服方寸匕。日三服。咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。悸者。加$u{桂枝}$w{五分}。小便不利者。加$u{茯苓}$w{五分}。腹中痛者。加$u{附子}$w{一枚。炮令坼}。泄利下重者。先以水五升。煮$u{薤白}$w{三升}。去滓。以散三方寸匕。内汤中。煮取一升半。分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":105,"yaoCount":10,"drinkNum":50,"yaoList":["甘草","枳实","芍药","柴胡","五味子","干姜","桂枝","茯苓","附子","薤白"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"十分","weight":250,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"十分","weight":250,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"十分","weight":250,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"JMfcgoRTH0J","amount":"十分","weight":250,"suffix":"","showName":"柴胡","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '105、$f{四逆散} 4味 $u{甘草}$w{炙} $u{枳实}$w{(破。水渍。炙干)} $u{芍药} $u{柴胡} 上四味。各十分。捣筛。白饮和服方寸匕。日三服。咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。悸者。加$u{桂枝}$w{五分}。小便不利者。加$u{茯苓}$w{五分}。腹中痛者。加$u{附子}$w{一枚。炮令坼}。泄利下重者。先以水五升。煮$u{薤白}$w{三升}。去滓。以散三方寸匕。内汤中。煮取一升半。分温再服。', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LOm2M56zCYG', 1, '{"title":"白头翁汤","description":"<p>106、$f{白头翁汤} 4味 </p>\n<p>$u{白头翁}$w{二两}    $u{黄柏}$w{三两}    $u{黄连}$w{三两}    $u{秦皮}$w{三两}</p>\n<p>\t上四味。以水七升。煮取二升。去滓。温服一升。不愈。更服一升。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":106,"yaoCount":4,"drinkNum":2,"yaoList":["白头翁","黄柏","黄连","秦皮"],"fangList":[],"fangYaoList":[{"yaoId":"Nosq7W5OJnv","amount":"二两","weight":200,"suffix":"","showName":"白头翁","extraProcess":"切"},{"yaoId":"Z5xEswEFq4S","amount":"三两","weight":300,"suffix":"","showName":"黄柏","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"三两","weight":300,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"Iru92bFSKGK","amount":"三两","weight":300,"suffix":"","showName":"秦皮","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '106、$f{白头翁汤} 4味 $u{白头翁}$w{二两} $u{黄柏}$w{三两} $u{黄连}$w{三两} $u{秦皮}$w{三两} 上四味。以水七升。煮取二升。去滓。温服一升。不愈。更服一升。', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IOWdG491VAR', 1, '{"title":"通脉四逆加猪胆汁汤","description":"<p>107、$f{通脉四逆加猪胆汁汤} 4味 </p>\n<p>$u{甘草}$w{二两。炙}    $u{附子}$w{大者一枚(生。去皮。破八片)}    $u{干姜}$w{三两。强人可四两}    $u{猪胆汁}$w{半合}</p>\n<p>\t上四味。以水三升。煮取一升二合。去滓。内猪胆汁。分温再服。$a{其脉即来。无猪胆。以羊胆代之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":107,"yaoCount":4,"drinkNum":2,"yaoList":["甘草","附子","干姜","猪胆汁"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚大者生","weight":150,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"KIP0kUQVkZG","amount":"半合","weight":50,"suffix":"","showName":"猪胆汁","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '107、$f{通脉四逆加猪胆汁汤} 4味 $u{甘草}$w{二两。炙} $u{附子}$w{大者一枚(生。去皮。破八片)} $u{干姜}$w{三两。强人可四两} $u{猪胆汁}$w{半合} 上四味。以水三升。煮取一升二合。去滓。内猪胆汁。分温再服。$a{其脉即来。无猪胆。以羊胆代之。}', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
